package com.yaseen.npcmind.tool.impl;
import com.yaseen.npcmind.tool.JsonArgs;
import com.yaseen.npcmind.entity.CompanionEntity;import com.yaseen.npcmind.tool.AITool;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.EquipmentSlot;
public final class LoadoutTool implements AITool{
 public String name(){return "prepare_loadout";} public String description(){return "Inspect or equip real companion equipment from its persistent inventory; never creates missing gear.";} public String schema(){return "{\"action\":\"inspect|equip\",\"slot\":number(optional),\"inventory_slot\":number(optional)}";}
 public String execute(CompanionEntity c,ServerPlayer p,String a){String act=MoveToTool.str(a,"action");if(!"equip".equals(act)){StringBuilder b=new StringBuilder("RESULT equipment=");for(int i=0;i<4;i++){EquipmentSlot es=slot(i);ItemStack s=c.getItemBySlot(es);if(!s.isEmpty())b.append(i).append(':').append(s.getHoverName().getString()).append(';');}return b.toString();}Integer inv=num(a,"inventory_slot"),slot=num(a,"slot");if(inv==null||slot==null||inv<0||inv>=c.getCompanionInventory().getContainerSize()||slot<0||slot>5)return "ERROR invalid_slot";ItemStack candidate=c.getCompanionInventory().getItem(inv);if(candidate.isEmpty())return "FAILED empty_inventory_slot";EquipmentSlot es=slot(slot);if(!isValidForSlot(candidate,es))return "FAILED item_not_valid_for_equipment_slot";ItemStack old=c.getItemBySlot(es);if(!old.isEmpty()&&!com.yaseen.npcmind.crafting.InventoryOps.canAdd(c.getCompanionInventory(),old))return "FAILED inventory_full_for_old_equipment";c.setItemSlot(es,candidate.copy());c.getCompanionInventory().setItem(inv,old);return "SUCCESS equipped="+candidate.getHoverName().getString()+" slot="+slot;}
 private boolean isValidForSlot(ItemStack s,EquipmentSlot slot){return com.yaseen.npcmind.entity.CompanionEquipmentManager.isValidForSlot(s,slot);} private EquipmentSlot slot(int i){return switch(i){case 0->EquipmentSlot.HEAD;case 1->EquipmentSlot.CHEST;case 2->EquipmentSlot.LEGS;case 3->EquipmentSlot.FEET;case 4->EquipmentSlot.MAINHAND;default->EquipmentSlot.OFFHAND;};}
 private Integer num(String s,String n){return JsonArgs.integer(s,n);}}
